import{_ as t,o as s,c as a,a0 as o}from"./chunks/framework.DVUHX04-.js";const n="/pi-extensions/assets/model-router-halt.DBk98G1g.png",k=JSON.parse('{"title":"model-router extension","description":"","frontmatter":{},"headers":[],"relativePath":"extensions/model-router.md","filePath":"extensions/model-router.md","lastUpdated":1789775493000}'),i={name:"extensions/model-router.md"};function r(l,e,h,d,c,p){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="model-router-extension" tabindex="-1">model-router extension <a class="header-anchor" href="#model-router-extension" aria-label="Permalink to &quot;model-router extension&quot;">​</a></h1><p>Recovers a pi session from a provider usage-limit (quota) halt without the user re-running the prompt. When the active model&#39;s provider reports a terminal usage-limit error and pi&#39;s own retries give up, the router runs the configured strategies in order: switch to a fallback model, or wait for the quota window to reset. When the session runs again, the halted turn resumes through one synthetic user message. The router switches back to the original model once the quota recovers and the session is idle.</p><p>Works from any session. It reads the OpenAI ChatGPT plan&#39;s quota windows through the Quota source module (<code>extensions/quota/source.ts</code>, issue #28), which owns the ChatGPT token refresh (ADR 0005).</p><h2 id="screenshot" tabindex="-1">Screenshot <a class="header-anchor" href="#screenshot" aria-label="Permalink to &quot;Screenshot&quot;">​</a></h2><p>A usage-limit halt and the <code>switch</code> recovery in one turn: the 429, the router notification, the resume message, and the fallback model&#39;s answer. The status bar has moved to the fallback model.</p><p><img src="'+n+`" alt="model-router halt and switch"></p><h2 id="behavior" tabindex="-1">Behavior <a class="header-anchor" href="#behavior" aria-label="Permalink to &quot;Behavior&quot;">​</a></h2><ul><li><strong>Quota halt detection.</strong> After a turn settles with an error, the router classifies the assistant message&#39;s error text. Only terminal usage-limit shapes start a Recovery; transient throttles and overloads stay with pi&#39;s built-in retry.</li><li><strong>Strategies, in Precedence order.</strong> <code>switch</code> moves the session to the first usable fallback model. <code>wait</code> arms a timer for the binding reset (the latest reset among the exhausted windows) and resumes when it confirms the quota is back.</li><li><strong>Bound.</strong> At most three full strategy cycles per failed prompt, then one error notification and a clean stop. A fallback that fails with its own usage limit advances the chain.</li><li><strong>Switch-back.</strong> While on a fallback the router set, the router switches back to the original model once the quota recovers and the session is idle.</li><li><strong>Cancel.</strong> User input cancels a pending wait. A manual model change cancels both the pending wait and the pending switch-back.</li><li><strong>Restart.</strong> A pending recovery is persisted in the session and re-armed on the next start, so waiting does not depend on the terminal staying open.</li><li><strong>Provider scope.</strong> The wait strategy and the switch-back only apply to the <code>openai-codex</code> (ChatGPT plan) provider, because that is what the Quota source reads; for any other provider only switch applies.</li></ul><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>The <code>modelRouter</code> section of <code>settings.json</code>. Project <code>&lt;cwd&gt;/.pi/settings.json</code> overrides global <code>~/.pi/agent/settings.json</code>, key by key.</p><table tabindex="0"><thead><tr><th>Key</th><th>Type</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Turn the router on or off.</td></tr><tr><td><code>precedence</code></td><td><code>(&quot;switch&quot; | &quot;wait&quot;)[]</code></td><td><code>[&quot;switch&quot;,&quot;wait&quot;]</code></td><td>Strategy order on a halt.</td></tr><tr><td><code>fallbacks</code></td><td><code>&quot;provider/model-id&quot;[]</code></td><td><code>[]</code></td><td>Ordered <code>&quot;provider/model-id&quot;</code> entries the switch strategy tries.</td></tr><tr><td><code>maxWaitMinutes</code></td><td><code>number</code> greater than 0</td><td><code>360</code></td><td>Only wait when the binding reset is within this many minutes.</td></tr></tbody></table><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;modelRouter&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;precedence&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;switch&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;wait&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;fallbacks&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;anthropic/claude-sonnet-4-5&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;google/gemini-3.5-flash&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;maxWaitMinutes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">360</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>A malformed value falls back to its default and is reported with one startup notification. A fallback entry whose model is missing or has no configured auth is skipped; if none are usable the router moves to the next strategy.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ul><li><strong>Resume.</strong> pi has no re-run-the-failed-turn API, so the router resumes the halted turn with one fixed user message (ADR 0006). That message is the only visible trace of a recovery.</li><li><strong>Token refresh.</strong> The Quota source refreshes an expired ChatGPT access token before reading, retries once after a 401, and otherwise reports the read failure. The router treats an unreadable quota as &quot;wait not viable&quot;.</li><li><strong>Seam.</strong> The decision logic lives in <code>router.ts</code>, which is engine-free and fully tested with injected quota reads, clock, timers, model lookups, and an action sink. <code>index.ts</code> is the thin pi wiring.</li></ul><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>Exactly four recovery-transition points, plus one per skipped-fallback summary:</p><ol><li>Wait starts, with the ETA.</li><li>Switch to a fallback.</li><li>Switch back to the original.</li><li>Recovery gave up (error level).</li></ol><h2 id="real-example-a-fallback-chain-walk" tabindex="-1">Real example: a fallback chain walk <a class="header-anchor" href="#real-example-a-fallback-chain-walk" aria-label="Permalink to &quot;Real example: a fallback chain walk&quot;">​</a></h2><p>Observed in a live session on 2026-09-14. The user typed <code>test</code> on <code>qwen-token-plan-individual/qwen3.8-max</code> while the token plan was exhausted. The error body carries <code>insufficient_quota</code>, which the classifier matches:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>13:06:38  ASSIST qwen3.8-max  stop=error</span></span>
<span class="line"><span>          429: {&quot;message&quot;:&quot;Your token-plan 1-week quota has been</span></span>
<span class="line"><span>          exhausted. The quota will reset at 09-19 15:43:00 UTC.&quot;,</span></span>
<span class="line"><span>          &quot;type&quot;:&quot;insufficient_quota&quot;,&quot;code&quot;:&quot;insufficient_quota&quot;}</span></span>
<span class="line"><span>          -&gt; router switched to qwen3.8-flash</span></span>
<span class="line"><span>13:07:15  ASSIST qwen3.8-flash  stop=error (same 429)</span></span>
<span class="line"><span>          -&gt; persisted recovery: {&quot;phase&quot;:&quot;on-fallback&quot;,</span></span>
<span class="line"><span>             &quot;original&quot;:&quot;qwen-token-plan-individual/qwen3.8-max&quot;,</span></span>
<span class="line"><span>             &quot;chainPos&quot;:2,</span></span>
<span class="line"><span>             &quot;fallbackInUse&quot;:&quot;qwen-token-plan-individual/qwen3.8-flash&quot;,</span></span>
<span class="line"><span>             &quot;cycles&quot;:1}</span></span>
<span class="line"><span>          -&gt; router sent the Recovery message; flash halted on it</span></span>
<span class="line"><span>          -&gt; chain advanced: chainPos 3,</span></span>
<span class="line"><span>             fallbackInUse llama.cpp/unsloth/qwen3.8-27b, cycles 2</span></span>
<span class="line"><span>          -&gt; router sent the Recovery message on the local model</span></span>
<span class="line"><span>13:07:24  ASSIST llama.cpp (unsloth/qwen3.8-27b) ran the resumed turn</span></span></code></pre></div><p>The wait strategy did not run: it applies only to <code>openai-codex</code>, so this recovery was a pure switch walk until the local model took over. The <code>model-router-pending</code> session entries above are also what re-arm the recovery if the session restarts mid-walk.</p><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><p>Transient throttles and overloads (pi&#39;s own retry), context overflow, and non-ChatGPT quota plans (the Quota source covers the ChatGPT plan in v1).</p>`,24)])])}const g=t(i,[["render",r]]);export{k as __pageData,g as default};
